-- fmdata.sql
-- Database dummy Penjualan Family Mart untuk XAMPP/phpMyAdmin
-- Dibuat otomatis: 40 tabel, total 3000 baris data INSERT yang saling terhubung.
-- Engine: InnoDB, Charset: utf8mb4

DROP DATABASE IF EXISTS `fmdata`;
CREATE DATABASE `fmdata` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `fmdata`;

-- Ringkasan jumlah data per tabel
-- roles: 6
-- departments: 6
-- employee_statuses: 3
-- store_types: 4
-- provinces: 4
-- cities: 8
-- districts: 16
-- stores: 12
-- shifts: 4
-- employees: 60
-- employee_shifts: 76
-- suppliers: 18
-- units: 8
-- product_categories: 10
-- product_subcategories: 20
-- brands: 24
-- products: 150
-- product_barcodes: 150
-- product_prices: 150
-- product_stock: 240
-- purchase_orders: 40
-- purchase_order_items: 160
-- goods_receipts: 35
-- goods_receipt_items: 140
-- membership_tiers: 4
-- customers: 175
-- memberships: 120
-- promotions: 20
-- promotion_products: 60
-- coupons: 50
-- payment_methods: 6
-- sales_orders: 250
-- sales_order_items: 480
-- payments: 250
-- return_reasons: 6
-- returns: 25
-- return_items: 50
-- inventory_adjustments: 60
-- expenses: 50
-- daily_cash_reconciliations: 50


SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `daily_cash_reconciliations`;
DROP TABLE IF EXISTS `expenses`;
DROP TABLE IF EXISTS `inventory_adjustments`;
DROP TABLE IF EXISTS `return_items`;
DROP TABLE IF EXISTS `returns`;
DROP TABLE IF EXISTS `return_reasons`;
DROP TABLE IF EXISTS `payments`;
DROP TABLE IF EXISTS `sales_order_items`;
DROP TABLE IF EXISTS `sales_orders`;
DROP TABLE IF EXISTS `payment_methods`;
DROP TABLE IF EXISTS `coupons`;
DROP TABLE IF EXISTS `promotion_products`;
DROP TABLE IF EXISTS `promotions`;
DROP TABLE IF EXISTS `memberships`;
DROP TABLE IF EXISTS `customers`;
DROP TABLE IF EXISTS `membership_tiers`;
DROP TABLE IF EXISTS `goods_receipt_items`;
DROP TABLE IF EXISTS `goods_receipts`;
DROP TABLE IF EXISTS `purchase_order_items`;
DROP TABLE IF EXISTS `purchase_orders`;
DROP TABLE IF EXISTS `product_stock`;
DROP TABLE IF EXISTS `product_prices`;
DROP TABLE IF EXISTS `product_barcodes`;
DROP TABLE IF EXISTS `products`;
DROP TABLE IF EXISTS `brands`;
DROP TABLE IF EXISTS `product_subcategories`;
DROP TABLE IF EXISTS `product_categories`;
DROP TABLE IF EXISTS `units`;
DROP TABLE IF EXISTS `suppliers`;
DROP TABLE IF EXISTS `employee_shifts`;
DROP TABLE IF EXISTS `employees`;
DROP TABLE IF EXISTS `shifts`;
DROP TABLE IF EXISTS `stores`;
DROP TABLE IF EXISTS `districts`;
DROP TABLE IF EXISTS `cities`;
DROP TABLE IF EXISTS `provinces`;
DROP TABLE IF EXISTS `store_types`;
DROP TABLE IF EXISTS `employee_statuses`;
DROP TABLE IF EXISTS `departments`;
DROP TABLE IF EXISTS `roles`;

SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE `roles` (
  `role_id` INT PRIMARY KEY,
  `role_name` VARCHAR(80) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `departments` (
  `department_id` INT PRIMARY KEY,
  `department_name` VARCHAR(80) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `employee_statuses` (
  `status_id` INT PRIMARY KEY,
  `status_name` VARCHAR(40) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `store_types` (
  `store_type_id` INT PRIMARY KEY,
  `type_name` VARCHAR(60) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `provinces` (
  `province_id` INT PRIMARY KEY,
  `province_name` VARCHAR(100) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `cities` (
  `city_id` INT PRIMARY KEY,
  `province_id` INT NOT NULL,
  `city_name` VARCHAR(100) NOT NULL,
  FOREIGN KEY (`province_id`) REFERENCES `provinces`(`province_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `districts` (
  `district_id` INT PRIMARY KEY,
  `city_id` INT NOT NULL,
  `district_name` VARCHAR(100) NOT NULL,
  FOREIGN KEY (`city_id`) REFERENCES `cities`(`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `stores` (
  `store_id` INT PRIMARY KEY,
  `store_code` VARCHAR(20) NOT NULL UNIQUE,
  `store_name` VARCHAR(120) NOT NULL,
  `store_type_id` INT NOT NULL,
  `district_id` INT NOT NULL,
  `address` VARCHAR(255) NOT NULL,
  `phone` VARCHAR(30),
  `opening_date` DATE,
  FOREIGN KEY (`store_type_id`) REFERENCES `store_types`(`store_type_id`),
  FOREIGN KEY (`district_id`) REFERENCES `districts`(`district_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `shifts` (
  `shift_id` INT PRIMARY KEY,
  `shift_name` VARCHAR(50) NOT NULL,
  `start_time` TIME NOT NULL,
  `end_time` TIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `employees` (
  `employee_id` INT PRIMARY KEY,
  `store_id` INT NOT NULL,
  `role_id` INT NOT NULL,
  `department_id` INT NOT NULL,
  `status_id` INT NOT NULL,
  `employee_code` VARCHAR(20) NOT NULL UNIQUE,
  `full_name` VARCHAR(120) NOT NULL,
  `gender` VARCHAR(20),
  `hire_date` DATE,
  `salary` DECIMAL(12,2),
  FOREIGN KEY (`store_id`) REFERENCES `stores`(`store_id`),
  FOREIGN KEY (`role_id`) REFERENCES `roles`(`role_id`),
  FOREIGN KEY (`department_id`) REFERENCES `departments`(`department_id`),
  FOREIGN KEY (`status_id`) REFERENCES `employee_statuses`(`status_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `employee_shifts` (
  `employee_shift_id` INT PRIMARY KEY,
  `employee_id` INT NOT NULL,
  `store_id` INT NOT NULL,
  `shift_id` INT NOT NULL,
  `work_date` DATE NOT NULL,
  `note` VARCHAR(120),
  FOREIGN KEY (`employee_id`) REFERENCES `employees`(`employee_id`),
  FOREIGN KEY (`store_id`) REFERENCES `stores`(`store_id`),
  FOREIGN KEY (`shift_id`) REFERENCES `shifts`(`shift_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `suppliers` (
  `supplier_id` INT PRIMARY KEY,
  `supplier_code` VARCHAR(20) NOT NULL UNIQUE,
  `supplier_name` VARCHAR(150) NOT NULL,
  `contact_name` VARCHAR(100),
  `phone` VARCHAR(30),
  `email` VARCHAR(120),
  `address` VARCHAR(255),
  `city_id` INT NOT NULL,
  FOREIGN KEY (`city_id`) REFERENCES `cities`(`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `units` (
  `unit_id` INT PRIMARY KEY,
  `unit_name` VARCHAR(60) NOT NULL,
  `abbreviation` VARCHAR(15) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `product_categories` (
  `category_id` INT PRIMARY KEY,
  `category_name` VARCHAR(100) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `product_subcategories` (
  `subcategory_id` INT PRIMARY KEY,
  `category_id` INT NOT NULL,
  `subcategory_name` VARCHAR(100) NOT NULL,
  FOREIGN KEY (`category_id`) REFERENCES `product_categories`(`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `brands` (
  `brand_id` INT PRIMARY KEY,
  `brand_name` VARCHAR(100) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `products` (
  `product_id` INT PRIMARY KEY,
  `sku` VARCHAR(30) NOT NULL UNIQUE,
  `product_name` VARCHAR(160) NOT NULL,
  `category_id` INT NOT NULL,
  `subcategory_id` INT NOT NULL,
  `brand_id` INT NOT NULL,
  `unit_id` INT NOT NULL,
  `supplier_id` INT NOT NULL,
  `cost_price` DECIMAL(12,2) NOT NULL,
  `retail_price` DECIMAL(12,2) NOT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  FOREIGN KEY (`category_id`) REFERENCES `product_categories`(`category_id`),
  FOREIGN KEY (`subcategory_id`) REFERENCES `product_subcategories`(`subcategory_id`),
  FOREIGN KEY (`brand_id`) REFERENCES `brands`(`brand_id`),
  FOREIGN KEY (`unit_id`) REFERENCES `units`(`unit_id`),
  FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`supplier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `product_barcodes` (
  `barcode_id` INT PRIMARY KEY,
  `product_id` INT NOT NULL,
  `barcode` VARCHAR(40) NOT NULL UNIQUE,
  FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `product_prices` (
  `price_id` INT PRIMARY KEY,
  `product_id` INT NOT NULL,
  `effective_date` DATE NOT NULL,
  `price` DECIMAL(12,2) NOT NULL,
  `cost_price` DECIMAL(12,2) NOT NULL,
  FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `product_stock` (
  `stock_id` INT PRIMARY KEY,
  `store_id` INT NOT NULL,
  `product_id` INT NOT NULL,
  `qty_on_hand` INT NOT NULL,
  `reorder_level` INT NOT NULL,
  `last_updated` DATETIME,
  UNIQUE KEY `uq_store_product` (`store_id`, `product_id`),
  FOREIGN KEY (`store_id`) REFERENCES `stores`(`store_id`),
  FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `purchase_orders` (
  `po_id` INT PRIMARY KEY,
  `po_number` VARCHAR(30) NOT NULL UNIQUE,
  `supplier_id` INT NOT NULL,
  `store_id` INT NOT NULL,
  `employee_id` INT NOT NULL,
  `order_date` DATE NOT NULL,
  `expected_date` DATE,
  `status` VARCHAR(40) NOT NULL,
  FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`supplier_id`),
  FOREIGN KEY (`store_id`) REFERENCES `stores`(`store_id`),
  FOREIGN KEY (`employee_id`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `purchase_order_items` (
  `po_item_id` INT PRIMARY KEY,
  `po_id` INT NOT NULL,
  `product_id` INT NOT NULL,
  `quantity` INT NOT NULL,
  `unit_cost` DECIMAL(12,2) NOT NULL,
  FOREIGN KEY (`po_id`) REFERENCES `purchase_orders`(`po_id`),
  FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `goods_receipts` (
  `receipt_id` INT PRIMARY KEY,
  `gr_number` VARCHAR(30) NOT NULL UNIQUE,
  `po_id` INT NOT NULL,
  `store_id` INT NOT NULL,
  `received_by` INT NOT NULL,
  `received_date` DATE NOT NULL,
  `status` VARCHAR(40) NOT NULL,
  FOREIGN KEY (`po_id`) REFERENCES `purchase_orders`(`po_id`),
  FOREIGN KEY (`store_id`) REFERENCES `stores`(`store_id`),
  FOREIGN KEY (`received_by`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `goods_receipt_items` (
  `gr_item_id` INT PRIMARY KEY,
  `receipt_id` INT NOT NULL,
  `product_id` INT NOT NULL,
  `quantity_received` INT NOT NULL,
  `unit_cost` DECIMAL(12,2) NOT NULL,
  FOREIGN KEY (`receipt_id`) REFERENCES `goods_receipts`(`receipt_id`),
  FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `membership_tiers` (
  `tier_id` INT PRIMARY KEY,
  `tier_name` VARCHAR(60) NOT NULL UNIQUE,
  `min_points` INT NOT NULL,
  `discount_percent` DECIMAL(5,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `customers` (
  `customer_id` INT PRIMARY KEY,
  `customer_code` VARCHAR(30) NOT NULL UNIQUE,
  `full_name` VARCHAR(120) NOT NULL,
  `gender` VARCHAR(20),
  `phone` VARCHAR(30),
  `email` VARCHAR(120),
  `birth_date` DATE,
  `district_id` INT,
  `registered_at` DATETIME,
  FOREIGN KEY (`district_id`) REFERENCES `districts`(`district_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `memberships` (
  `membership_id` INT PRIMARY KEY,
  `customer_id` INT NOT NULL UNIQUE,
  `tier_id` INT NOT NULL,
  `member_no` VARCHAR(30) NOT NULL UNIQUE,
  `joined_date` DATE NOT NULL,
  `points` INT NOT NULL DEFAULT 0,
  `status` VARCHAR(30) NOT NULL,
  FOREIGN KEY (`customer_id`) REFERENCES `customers`(`customer_id`),
  FOREIGN KEY (`tier_id`) REFERENCES `membership_tiers`(`tier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `promotions` (
  `promotion_id` INT PRIMARY KEY,
  `promo_code` VARCHAR(30) NOT NULL UNIQUE,
  `promo_name` VARCHAR(120) NOT NULL,
  `start_date` DATE NOT NULL,
  `end_date` DATE NOT NULL,
  `discount_type` VARCHAR(20) NOT NULL,
  `discount_value` DECIMAL(12,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `promotion_products` (
  `promo_product_id` INT PRIMARY KEY,
  `promotion_id` INT NOT NULL,
  `product_id` INT NOT NULL,
  UNIQUE KEY `uq_promo_product` (`promotion_id`, `product_id`),
  FOREIGN KEY (`promotion_id`) REFERENCES `promotions`(`promotion_id`),
  FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `coupons` (
  `coupon_id` INT PRIMARY KEY,
  `customer_id` INT NOT NULL,
  `promotion_id` INT NOT NULL,
  `coupon_code` VARCHAR(40) NOT NULL UNIQUE,
  `issued_date` DATE NOT NULL,
  `expired_date` DATE NOT NULL,
  `is_used` TINYINT(1) NOT NULL DEFAULT 0,
  FOREIGN KEY (`customer_id`) REFERENCES `customers`(`customer_id`),
  FOREIGN KEY (`promotion_id`) REFERENCES `promotions`(`promotion_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `payment_methods` (
  `method_id` INT PRIMARY KEY,
  `method_name` VARCHAR(60) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `sales_orders` (
  `sale_id` INT PRIMARY KEY,
  `invoice_number` VARCHAR(40) NOT NULL UNIQUE,
  `store_id` INT NOT NULL,
  `customer_id` INT NULL,
  `cashier_id` INT NOT NULL,
  `sale_datetime` DATETIME NOT NULL,
  `subtotal` DECIMAL(14,2) NOT NULL,
  `discount_total` DECIMAL(14,2) NOT NULL,
  `tax_total` DECIMAL(14,2) NOT NULL,
  `grand_total` DECIMAL(14,2) NOT NULL,
  `status` VARCHAR(30) NOT NULL,
  FOREIGN KEY (`store_id`) REFERENCES `stores`(`store_id`),
  FOREIGN KEY (`customer_id`) REFERENCES `customers`(`customer_id`),
  FOREIGN KEY (`cashier_id`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `sales_order_items` (
  `sale_item_id` INT PRIMARY KEY,
  `sale_id` INT NOT NULL,
  `product_id` INT NOT NULL,
  `promo_id` INT NULL,
  `quantity` INT NOT NULL,
  `unit_price` DECIMAL(12,2) NOT NULL,
  `discount_amount` DECIMAL(12,2) NOT NULL DEFAULT 0,
  `line_total` DECIMAL(14,2) NOT NULL,
  FOREIGN KEY (`sale_id`) REFERENCES `sales_orders`(`sale_id`),
  FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`),
  FOREIGN KEY (`promo_id`) REFERENCES `promotions`(`promotion_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `payments` (
  `payment_id` INT PRIMARY KEY,
  `sale_id` INT NOT NULL,
  `method_id` INT NOT NULL,
  `paid_amount` DECIMAL(14,2) NOT NULL,
  `payment_time` DATETIME NOT NULL,
  `reference_no` VARCHAR(60),
  `status` VARCHAR(30) NOT NULL,
  FOREIGN KEY (`sale_id`) REFERENCES `sales_orders`(`sale_id`),
  FOREIGN KEY (`method_id`) REFERENCES `payment_methods`(`method_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `return_reasons` (
  `reason_id` INT PRIMARY KEY,
  `reason_name` VARCHAR(100) NOT NULL UNIQUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `returns` (
  `return_id` INT PRIMARY KEY,
  `sale_id` INT NOT NULL,
  `customer_id` INT NULL,
  `handled_by` INT NOT NULL,
  `return_date` DATETIME NOT NULL,
  `reason_id` INT NOT NULL,
  `refund_amount` DECIMAL(14,2) NOT NULL,
  `status` VARCHAR(30) NOT NULL,
  FOREIGN KEY (`sale_id`) REFERENCES `sales_orders`(`sale_id`),
  FOREIGN KEY (`customer_id`) REFERENCES `customers`(`customer_id`),
  FOREIGN KEY (`handled_by`) REFERENCES `employees`(`employee_id`),
  FOREIGN KEY (`reason_id`) REFERENCES `return_reasons`(`reason_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `return_items` (
  `return_item_id` INT PRIMARY KEY,
  `return_id` INT NOT NULL,
  `sale_item_id` INT NOT NULL,
  `product_id` INT NOT NULL,
  `quantity` INT NOT NULL,
  `refund_amount` DECIMAL(14,2) NOT NULL,
  FOREIGN KEY (`return_id`) REFERENCES `returns`(`return_id`),
  FOREIGN KEY (`sale_item_id`) REFERENCES `sales_order_items`(`sale_item_id`),
  FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `inventory_adjustments` (
  `adjustment_id` INT PRIMARY KEY,
  `store_id` INT NOT NULL,
  `product_id` INT NOT NULL,
  `employee_id` INT NOT NULL,
  `adjustment_date` DATETIME NOT NULL,
  `qty_change` INT NOT NULL,
  `reason` VARCHAR(80) NOT NULL,
  `note` VARCHAR(160),
  FOREIGN KEY (`store_id`) REFERENCES `stores`(`store_id`),
  FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`),
  FOREIGN KEY (`employee_id`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `expenses` (
  `expense_id` INT PRIMARY KEY,
  `store_id` INT NOT NULL,
  `expense_date` DATE NOT NULL,
  `expense_category` VARCHAR(80) NOT NULL,
  `amount` DECIMAL(14,2) NOT NULL,
  `description` VARCHAR(160),
  FOREIGN KEY (`store_id`) REFERENCES `stores`(`store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `daily_cash_reconciliations` (
  `recon_id` INT PRIMARY KEY,
  `store_id` INT NOT NULL,
  `recon_date` DATE NOT NULL,
  `opening_cash` DECIMAL(14,2) NOT NULL,
  `cash_sales` DECIMAL(14,2) NOT NULL,
  `cash_refunds` DECIMAL(14,2) NOT NULL,
  `expected_cash` DECIMAL(14,2) NOT NULL,
  `actual_cash` DECIMAL(14,2) NOT NULL,
  `variance` DECIMAL(14,2) NOT NULL,
  `checked_by` INT NOT NULL,
  FOREIGN KEY (`store_id`) REFERENCES `stores`(`store_id`),
  FOREIGN KEY (`checked_by`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

START TRANSACTION;

